SELECT id, symbol, interval_code, candle_open_time, generated_at, UNIX_TIMESTAMP(generated_at) AS gen_epoch, created_at, signal_mode, decision, original_decision, total_score, confidence_score, latest_price FROM crypto_ai.trade_signal WHERE id IN (156852,166821,168277,172201,172588,176934) ORDER BY id;
SELECT id, interval_code, candle_open_time, generated_at, decision, original_decision, total_score FROM crypto_ai.trade_signal WHERE symbol='DOGEUSDT' AND interval_code IN ('5m','1h') AND generated_at BETWEEN (SELECT generated_at FROM crypto_ai.trade_signal WHERE id=168277) - INTERVAL 70 MINUTE AND (SELECT generated_at FROM crypto_ai.trade_signal WHERE id=168277) ORDER BY generated_at DESC LIMIT 8;